  'HTTPCode_ELB_503 — 정상 타깃 없음': { en: 'HTTPCode_ELB_503 — no healthy targets', zh: 'HTTPCode_ELB_503 — 无健康目标', ja: 'HTTPCode_ELB_503 — 正常なターゲットなし' },
