  'HTTPCode_Target_5XX — 백엔드 애플리케이션 오류': { en: 'HTTPCode_Target_5XX — backend application errors', zh: 'HTTPCode_Target_5XX — 后端应用错误', ja: 'HTTPCode_Target_5XX — バックエンドアプリケーションエラー' },
