  'ActiveFlowCount — 활성 플로우, 급증/급감으로 트래픽 이상 감지': { en: 'ActiveFlowCount — active flows; sudden spikes/drops signal traffic anomalies', zh: 'ActiveFlowCount — 活跃流；骤增/骤减可发现流量异常', ja: 'ActiveFlowCount — アクティブフロー、急増/急減でトラフィック異常を検知' },
  'NewFlowCount(선택 기간 누적) — 연결 수립률': { en: 'NewFlowCount (sum over selected range) — connection establishment rate', zh: 'NewFlowCount（所选时间段累计）— 连接建立速率', ja: 'NewFlowCount（選択期間累計）— 接続確立率' },
  'TCP_Target_Reset_Count(선택 기간 누적) — 타깃발 RST 급증 = 백엔드 문제 강한 신호 (앱 크래시/포트 닫힘/백로그 초과)': { en: 'TCP_Target_Reset_Count (sum over selected range) — a spike in target-sent RSTs is a strong backend-problem signal (app crash / closed port / backlog overflow)', zh: 'TCP_Target_Reset_Count（所选时间段累计）— 目标端 RST 骤增是后端问题的强信号（应用崩溃/端口关闭/积压超限）', ja: 'TCP_Target_Reset_Count（選択期間累計）— ターゲット発 RST の急増はバックエンド問題の強い兆候（アプリクラッシュ/ポート閉鎖/バックログ超過）' },
  'TCP_ELB_Reset_Count(선택 기간 누적) — NLB발 RST 급증 = idle timeout(350초)/비대칭 라우팅': { en: 'TCP_ELB_Reset_Count (sum over selected range) — a spike in NLB-sent RSTs = idle timeout (350s) / asymmetric routing', zh: 'TCP_ELB_Reset_Count（所选时间段累计）— NLB 端 RST 骤增 = 空闲超时（350 秒）/非对称路由', ja: 'TCP_ELB_Reset_Count（選択期間累計）— NLB 発 RST の急増 = アイドルタイムアウト（350秒）/非対称ルーティング' },
  'TCP_Client_Reset_Count(선택 기간 누적) — 클라이언트발 RST': { en: 'TCP_Client_Reset_Count (sum over selected range) — client-sent RSTs', zh: 'TCP_Client_Reset_Count（所选时间段累计）— 客户端发出的 RST', ja: 'TCP_Client_Reset_Count（選択期間累計）— クライアント発 RST' },
  'ProcessedBytes(선택 기간 누적)': { en: 'ProcessedBytes (sum over selected range)', zh: 'ProcessedBytes（所选时间段累计）', ja: 'ProcessedBytes（選択期間累計）' },
  'PortAllocationErrorCount — SNAT 소스 포트 고갈, >0이면 연결 실패 발생 (놓치기 쉬운 원인)': { en: 'PortAllocationErrorCount — SNAT source-port exhaustion; >0 means connection failures are occurring (an easily missed cause)', zh: 'PortAllocationErrorCount — SNAT 源端口耗尽；>0 即发生连接失败（易被忽视的原因）', ja: 'PortAllocationErrorCount — SNAT ソースポート枯渇、>0 なら接続失敗が発生中（見落としやすい原因）' },
  'UnhealthyRoutingFlowCount — 정상 타깃이 없어 라우팅 실패한 플로우': { en: 'UnhealthyRoutingFlowCount — flows that failed to route because no healthy target was available', zh: 'UnhealthyRoutingFlowCount — 因无健康目标而路由失败的流', ja: 'UnhealthyRoutingFlowCount — 正常なターゲットがなくルーティングに失敗したフロー' },
