  'TargetTLSNegotiationErrorCount — 타깃 측 TLS 협상 실패': { en: 'TargetTLSNegotiationErrorCount — target-side TLS negotiation failures', zh: 'TargetTLSNegotiationErrorCount — 目标端 TLS 协商失败', ja: 'TargetTLSNegotiationErrorCount — ターゲット側 TLS ネゴシエーション失敗' },
  'ConsumedLCUs(선택 기간 누적)': { en: 'ConsumedLCUs (sum over selected range)', zh: 'ConsumedLCUs（所选时间段累计）', ja: 'ConsumedLCUs（選択期間累計）' },
  'RST 카운트와 타깃 헬스가 진단의 핵심': { en: 'RST counts and target health are the diagnostic core', zh: 'RST 计数与目标健康是诊断核心', ja: 'RST カウントとターゲットヘルスが診断の要' },
